package io.beep.core.adapter.out.postgres;
import static org.assertj.core.api.Assertions.*;
import io.beep.core.app.port.*;
import io.beep.core.domain.user.*;
import io.beep.core.domain.workspace.Workspace;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.jooq.DSLContext;
import org.jooq.SQLDialect;
import org.jooq.impl.DSL;
import org.junit.jupiter.api.*;
import org.postgresql.ds.PGSimpleDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
class EnterpriseIT {
 static DSLContext db;static String jdbc,user,password;static final Instant NOW=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);PostgresEnterpriseAdapter data;Workspace ws;User owner;
 @BeforeAll static void setup(){var pg=new PGSimpleDataSource();String url=System.getenv("TEST_DATABASE_URL");if(url==null||url.isBlank()){var c=new PostgreSQLContainer<>("postgres:16-alpine");c.start();url=c.getJdbcUrl();pg.setUser(c.getUsername());pg.setPassword(c.getPassword());}pg.setUrl(url);jdbc=url;user=pg.getUser();password=pg.getPassword();var f=Flyway.configure().dataSource(pg).cleanDisabled(false).load();f.clean();f.migrate();f.validate();db=DSL.using(pg,SQLDialect.POSTGRES);}
 @BeforeEach void init(){db.execute("TRUNCATE users,slugs,platform_nodes,shared_rate_limits CASCADE");owner=User.register(UUID.randomUUID(),new Email("enterprise@example.org"),"hash","fr",NOW).verifyEmail(NOW);new PostgresUserAdapter(db).insert(owner);ws=new PostgresWorkspaceAdapter(db).ensure(Workspace.personal(UUID.randomUUID(),owner.id(),"Enterprise",NOW));data=new PostgresEnterpriseAdapter(db);save(1);}
 Map<String,Object> contract(int v){return new LinkedHashMap<>(Map.ofEntries(Map.entry("version",v),Map.entry("reference","ACME-2026"),Map.entry("status","active"),Map.entry("startsAt",NOW.minusSeconds(60).toString()),Map.entry("endsAt",NOW.plus(Duration.ofDays(365)).toString()),Map.entry("slaBp",9990),Map.entry("dpaReference","DPA-2026"),Map.entry("dpaSha256","a".repeat(64)),Map.entry("retentionDays",730),Map.entry("ipAllowlist",List.of("192.0.2.0/24")),Map.entry("brandName","ACME"),Map.entry("brandColor","#153d35")));}
 void save(int v){db.transaction(c->new PostgresEnterpriseAdapter(c.dsl()).saveContract(ws.id(),contract(v),Map.of(),"encrypted-secret",owner.id(),NOW));}
 @Test void contractVersionsCannotOverwriteConcurrentStaffChanges(){assertThat(data.contract(ws.id()).orElseThrow()).containsEntry("version",1).doesNotContainKey("sso_secret_cipher");assertThatThrownBy(()->save(1)).hasMessageContaining("conflict");save(2);assertThat(data.contract(ws.id()).orElseThrow()).containsEntry("version",2);}
 @Test void ssoStateIsSingleUseExpiringAndInvalidatedOnContractChange(){data.state("state",ws.id(),1,"encrypted","nonce",NOW.plusSeconds(600));assertThat(data.consumeState("state",NOW)).isPresent();assertThat(data.consumeState("state",NOW)).isEmpty();data.state("expired",ws.id(),1,"encrypted","nonce",NOW.minusSeconds(1));assertThat(data.consumeState("expired",NOW)).isEmpty();data.state("stale",ws.id(),1,"encrypted","nonce",NOW.plusSeconds(600));save(2);assertThat(data.consumeState("stale",NOW)).isEmpty();}
 UUID app(){UUID id=UUID.randomUUID();data.app(ws.id(),Map.of("id",id,"name","App","scheme","acme","androidStore","https://play.google.com/store/apps/details?id=org.acme","iosStore","https://apps.apple.com/app/id123"),NOW);return id;}
 @Test void deferredTokensAreBoundToAppPlatformAndExpire(){UUID app=app();data.deferred("hash",app,"encrypted-payload","android",NOW,NOW.plusSeconds(86400));assertThat(data.consumeDeferred("hash",UUID.randomUUID(),"android",NOW)).isEmpty();assertThat(data.consumeDeferred("hash",app,"ios",NOW)).isEmpty();assertThat(data.consumeDeferred("hash",app,"android",NOW)).contains("encrypted-payload");assertThat(data.consumeDeferred("hash",app,"android",NOW)).isEmpty();data.deferred("expired",app,"encrypted","ios",NOW,NOW.plusSeconds(1));assertThat(data.consumeDeferred("expired",app,"ios",NOW.plusSeconds(1))).isEmpty();}
 @Test void disablingAppRevokesPendingHandoffs(){UUID app=app();data.deferred("hash",app,"encrypted","android",NOW,NOW.plusSeconds(60));data.disableApp(ws.id(),app);assertThat(data.consumeDeferred("hash",app,"android",NOW)).isEmpty();}
 @Test void sessionProofsAreScopedVersionedAndCascadeOnLogout(){var sessions=new PostgresSessionAdapter(db);sessions.insert(new SessionRepository.Session(UUID.randomUUID(),owner.id(),"session",NOW,NOW.plusSeconds(60)));data.proof("session",ws.id(),1);assertThat(data.hasProof("session",ws.id(),1)).isTrue();assertThat(data.hasProof("session",ws.id(),2)).isFalse();assertThat(data.hasProof("session",UUID.randomUUID(),1)).isFalse();sessions.delete("session");assertThat(data.hasProof("session",ws.id(),1)).isFalse();}
 @Test void mfaProofIsOnlyAttachedAfterCompletion(){new PostgresSessionAdapter(db).insert(new SessionRepository.Session(UUID.randomUUID(),owner.id(),"session",NOW,NOW.plusSeconds(600)));data.pendingProof("mfa",ws.id(),1,NOW.plusSeconds(60));assertThat(data.hasProof("session",ws.id(),1)).isFalse();data.completeProof("mfa","session",NOW);assertThat(data.hasProof("session",ws.id(),1)).isTrue();}
 @Test void sharedLimiterUsesAtomicDatabaseCountsAcrossInstances()throws Exception{var a=new PostgresRateLimiterAdapter(db);var b=new PostgresRateLimiterAdapter(db);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var work=new ArrayList<Callable<Boolean>>();for(int i=0;i<25;i++){var limiter=i%2==0?a:b;work.add(()->limiter.tryAcquire("same-ip",10,Duration.ofMinutes(1)));}long accepted=0;for(var f:pool.invokeAll(work))if(f.get())accepted++;assertThat(accepted).isEqualTo(10);}a.reset("same-ip");assertThat(b.tryAcquire("same-ip",10,Duration.ofMinutes(1))).isTrue();}
 @Test void effectiveRetentionAndBrandRightsFollowActiveContract(){assertThat(db.fetchOne("SELECT beep_effective_right(?,'analytics.retention_days')",ws.id()).get(0,Long.class)).isEqualTo(730L);assertThat(db.fetchOne("SELECT beep_effective_right(?,'features.bio_badge_removable')",ws.id()).get(0,Long.class)).isEqualTo(1L);var c=contract(2);c.put("status","expired");db.transaction(t->new PostgresEnterpriseAdapter(t.dsl()).saveContract(ws.id(),c,Map.of(),"",owner.id(),NOW));assertThat(db.fetchOne("SELECT beep_effective_right(?,'analytics.retention_days')",ws.id()).get(0,Long.class)).isEqualTo(30L);}
 @Test void sdkArtifactsAreImmutableButCanBeRevoked(){var b=new HashMap<String,Object>(Map.of("platform","android","version","0.1.0","url","https://sdk.example/archive.zip","sha256","b".repeat(64),"status","active","minimumVersion","0.1.0"));data.sdk(b,owner.id(),NOW);b.put("status","revoked");data.sdk(b,owner.id(),NOW);b.put("sha256","c".repeat(64));assertThatThrownBy(()->data.sdk(b,owner.id(),NOW)).hasMessage("conflict");}
 @Test void reviewsCaptureActualMembershipAndScheduleNinetyDays(){data.review(ws.id(),"approved","Quarterly review",owner.id(),NOW);var r=db.fetchSingle("SELECT snapshot::text,due_at FROM access_reviews");assertThat(r.get(0,String.class)).contains(owner.id().toString()).contains("owner");assertThat(r.get(1,OffsetDateTime.class).toInstant()).isEqualTo(NOW.plus(Duration.ofDays(90)));}
 @Test void failoverIsAssistedAndRequiresAStaleNode(){data.heartbeat("node","redirector","eu",Map.of("processors",2),NOW);assertThatThrownBy(()->data.failover("node",null,"request","Incident",owner.id(),NOW)).hasMessage("conflict");var result=data.failover("node",null,"request","Incident",owner.id(),NOW.plusSeconds(91));assertThat(result).containsEntry("automatic",false);assertThatThrownBy(()->data.failover("node",null,"request","Incident",owner.id(),NOW.plusSeconds(92))).hasMessage("conflict");data.failover("",(UUID)result.get("id"),"confirm","Promoted externally",owner.id(),NOW.plusSeconds(93));assertThat(db.fetchValue("SELECT status FROM assisted_failovers")).isEqualTo("confirmed");}
 @Test void accountErasureCascadesEnterpriseSecretsAndMobileData(){UUID app=app();data.deferred("hash",app,"encrypted","ios",NOW,NOW.plusSeconds(60));data.bindIdentity(ws.id(),"https://idp.example","subject",owner.id());new PostgresPrivacyAdapter(db).erase(owner.id());for(String table:List.of("enterprise_contracts","mobile_apps","deferred_tokens","enterprise_sso_identities"))assertThat(db.fetchValue("SELECT count(*) FROM "+table)).isEqualTo(0L);}
 @Test void namedJobLocksExcludeAnotherWorkerAndReleaseAfterCompletion()throws Exception{var first=new PostgresJobLockAdapter(jdbc,user,password);var second=new PostgresJobLockAdapter(jdbc,user,password);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var future=pool.submit(()->first.run("phase5.concurrency",()->{entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("timeout");}catch(InterruptedException e){throw new IllegalStateException(e);}return "first";}));try{assertThat(entered.await(5,TimeUnit.SECONDS)).isTrue();assertThat(second.run("phase5.concurrency",()->{throw new AssertionError("concurrent job entered");})).contains("skipped");}finally{release.countDown();}assertThat(future.get(5,TimeUnit.SECONDS)).isEqualTo("first");assertThat(second.run("phase5.concurrency",()->"next")).isEqualTo("next");}}
 @Test void unavailableReadReplicaFallsBackToPrimary(){try(var reader=new ReplicaAnalyticsAdapter(db,"jdbc:postgresql://127.0.0.1:1/missing","test","test")){assertThat(reader.totals(AnalyticsRepository.Resource.LINK,UUID.randomUUID(),LocalDate.now(),LocalDate.now()).clicks()).isZero();}}
}
